        Matrix pow(long power) {
            Matrix result = new Matrix(size);
            for (int i = 0; i < size; i++) result.mat[i][i] = 1;
            Matrix base = this;
            while (power > 0) {
                if ((power & 1) == 1) result = result.multiply(base);
                base = base.multiply(base);
                power >>= 1;
            }
