import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;
    static final int MAXLEN = 5;

    static class Matrix {
        int size;
        int[][] data;

        Matrix(int size) {
            this.size = size;
            data = new int[size][size];
        }

        Matrix multiply(Matrix other) {
            Matrix result = new Matrix(size);
            for (int i = 0; i < size; i++) {
                for (int k = 0; k < size; k++) {
                    if (data[i][k] == 0) continue;
                    for (int j = 0; j < size; j++) {
                        result.data[i][j] = (result.data[i][j] + (long) data[i][k] * other.data[k][j]) % MOD;
                    }
                }
            }
            return result;
        }

        Matrix pow(long exponent) {
            Matrix result = new Matrix(size);
            for (int i = 0; i < size; i++) result.data[i][i] = 1;
            Matrix base = this;
            while (exponent > 0) {
                if ((exponent & 1) == 1) result = result.multiply(base);
                base = base.multiply(base);
                exponent >>= 1;
            }
            return result;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        long m = Long.parseLong(parts[1]);

        List<String> words = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            words.add(br.readLine().trim());
        }

        // Precompute valid transitions for each word
        Map<String, List<String>> transitions = new HashMap<>();
        for (String word : words) {
            List<String> list = new ArrayList<>();
            for (int len = 1; len <= word.length(); len++) {
                list.add(word.substring(0, len));
            }
            transitions.put(word, list);
        }

        // Build state transitions for a single word
        // State is the current suffix (up to MAXLEN-1 characters)
        // For each state and possible next character, determine the next state and whether a word is completed
        Map<String, Map<Character, List<String>>> stateTransitions = new HashMap<>();
        Set<String> allStates = new HashSet<>();
        allStates.add("");
        for (String word : words) {
            for (int len = 1; len < word.length(); len++) {
                allStates.add(word.substring(0, len));
            }
        }

        for (String state : allStates) {
            Map<Character, List<String>> charTransitions = new HashMap<>();
            for (char c = 'a'; c <= 'z'; c++) {
                String newState = (state + c).substring(1);
                List<String> completedWords = new ArrayList<>();
                for (String word : words) {
                    if (word.endsWith(newState) && word.length() >= newState.length()) {
                        completedWords.add(word);
                    }
                }
                charTransitions.put(c, completedWords);
            }
            stateTransitions.put(state, charTransitions);
        }

        // Build the transition matrix for the automaton
        // States are pairs of (top_state, bottom_state)
        // Each state represents the current suffix for both hints
        List<String> statesList = new ArrayList<>(allStates);
        int numStates = statesList.size();
        Map<String, Integer> stateIndex = new HashMap<>();
        for (int i = 0; i < numStates; i++) {
            stateIndex.put(statesList.get(i), i);
        }

        // Create the combined state transition matrix
        int totalStates = numStates * numStates;
        Matrix transitionMatrix = new Matrix(totalStates);

        for (int i = 0; i < numStates; i++) {
            String topState = statesList.get(i);
            for (int j = 0; j < numStates; j++) {
                String bottomState = statesList.get(j);
                int fromState = i * numStates + j;

                for (char c = 'a'; c <= 'z'; c++) {
                    // Compute next top state
                    String nextTop = (topState + c).substring(1);
                    int nextTopIdx = stateIndex.get(nextTop);

                    // Compute next bottom state
                    String nextBottom = (bottomState + c).substring(1);
                    int nextBottomIdx = stateIndex.get(nextBottom);

                    int toState = nextTopIdx * numStates + nextBottomIdx;

                    // Check if any word is completed in both hints
