            for (int i = 0; i < size; i++) {
                for (int k = 0; k < size; k++) {
                    if (mat[i][k] == 0) continue;
                    for (int j = 0; j < size; j++) {
                        result.mat[i][j] = (result.mat[i][j] + (long) mat[i][k] * other.mat[k][j]) % MOD;
                    }
                }
            }
            return result;
        }

        Matrix pow(long exp) {
            Matrix result = new Matrix(size);
            for (int i = 0; i < size; i++) result.mat[i][i] = 1;
            Matrix base = this;
            while (exp > 0) {
                if ((exp & 1) == 1) result = result.multiply(base);
                base = base.multiply(base);
                exp >>= 1;
            }
            return result;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        long m = Long.parseLong(parts[1]);
        List<String> words = new ArrayList<>();
        for (int i = 0; i < n; i++) words.add(br.readLine());

        // Build trie
        int maxNode = 1;
        int[][] trie = new int[7][26]; // max depth 5, so max nodes 6 (root + 5)
        int[] wordEnd = new int[7]; // wordEnd[node] = 1 if node is end of a word
        Arrays.fill(wordEnd, 0);
        for (String word : words) {
            int node = 0;
            for (char c : word.toCharArray()) {
                int idx = c - 'a';
                if (trie[node][idx] == 0) {
                    trie[node][idx] = maxNode++;
                }
                node = trie[node][idx];
            }
            wordEnd[node] = 1;
        }

        // Build transition matrix
        int size = maxNode;
        Matrix trans = new Matrix(size);
        for (int u = 0; u < size; u++) {
            for (int c = 0; c < 26; c++) {
                int v = trie[u][c];
                if (v == 0) continue;
                if (wordEnd[v] == 1) {
                    trans.mat[u][0] += 1; // transition to root
                    trans.mat[u][0] %= MOD;
                    trans.mat[u][v] += 1; // stay at v
                    trans.mat[u][v] %= MOD;
                } else {
                    trans.mat[u][v] += 1;
                }
            }
        }

        Matrix result = trans.pow(m);
        System.out.println(result.mat[0][0]);
    }
}
