import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;

    static class Matrix {
        int size;
        int[][] mat;

        Matrix(int size) {
            this.size = size;
            mat = new int[size][size];
        }

        Matrix multiply(Matrix other) {
            Matrix res = new Matrix(size);
            for (int i = 0; i < size; i++) {
                for (int k = 0; k < size; k++) {
                    if (mat[i][k] == 0) continue;
                    for (int j = 0; j < size; j++) {
                        res.mat[i][j] = (res.mat[i][j] + (long) mat[i][k] * other.mat[k][j]) % MOD;
                    }
                }
            }
            return res;
        }

        Matrix pow(long exp) {
            Matrix res = new Matrix(size);
            for (int i = 0; i < size; i++) res.mat[i][i] = 1;
            Matrix base = this;
            while (exp > 0) {
                if ((exp & 1) == 1) res = res.multiply(base);
                base = base.multiply(base);
                exp >>= 1;
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        long m = Long.parseLong(parts[1]);

        List<String> words = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            words.add(br.readLine().trim());
        }

        // Collect all possible lengths of words
        Set<Integer> lengths = new TreeSet<>();
        for (String w : words) lengths.add(w.length());
        List<Integer> lenList = new ArrayList<>(lengths);
        int maxL = lenList.isEmpty() ? 0 : lenList.get(lenList.size() - 1);

        // Build the transition matrix
        int size = maxL;
        Matrix mat = new Matrix(size);
        for (int i = 0; i < size; i++) {
            for (int l : lenList) {
                int next = i + l;
                if (next <= maxL) {
                    mat.mat[i][next - 1]++;
                }
            }
        }

        // Compute mat^m
        Matrix powered = mat.pow(m);

        // Sum all entries in the first row
        long ans = 0;
        for (int j = 0; j < size; j++) {
            ans = (ans + powered.mat[0][j]) % MOD;
        }

        System.out.println(ans);
    }
}
