import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;
    static long[][] matMul(long[][] a, long[][] b) {
        int n = a.length;
        long[][] c = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (a[i][j] == 0) continue;
                for (int k = 0; k < n; k++) {
                    c[i][k] = (c[i][k] + a[i][j] * b[j][k]) % MOD;
                }
            }
        }
        return c;
    }
    static long[][] matPow(long[][] a, long p) {
        int n = a.length;
        long[][] res = new long[n][n];
        for (int i = 0; i < n; i++) res[i][i] = 1;
        while (p > 0) {
            if ((p & 1) == 1) res = matMul(res, a);
            a = matMul(a, a);
            p >>= 1;
        }
        return res;
